mapper.select:
SELECT count(*) FROM t_agent_account a1 LEFT JOIN t_agent_account a2 ON a1.parent_agent_code = a2.agent_code LEFT JOIN sys_user s on a1.sys_user_id = s.user_id LEFT JOIN t_withdrawal_record r on a1.agent_code = r.agent_code WHERE a1.sys_user_id != 1
AND a2.agent_name like concat('%', #{parentAgentName}, '%')
AND a1.agent_name like concat('%', #{agentName}, '%')
AND a1.is_real_name = #{isRealName}
AND a1.is_enabled = #{isEnabled}
AND a1.level = #{level}
ORDER BY a1.create_time desc

SELECT a1.agent_account_id as agentAccountId, s.user_id as sysUserId, s.user_name as sysUserName, a1.parent_agent_code as parentAgentCode, a2.agent_name as parentAgentName, a1.agent_code as agentCode, a1.agent_name as agentName, a1.level as level, a1.is_real_name as isRealName, a1.phone as phone, a1.is_enabled as isEnabled, a1.is_encrypt as isEncrypt, a1.create_time as createTime, r.balance as balance FROM t_agent_account a1 LEFT JOIN t_agent_account a2 ON a1.parent_agent_code = a2.agent_code LEFT JOIN sys_user s on a1.sys_user_id = s.user_id LEFT JOIN t_withdrawal_record r on a1.agent_code = r.agent_code WHERE a1.sys_user_id != 1
AND a2.agent_name like concat('%', #{parentAgentName}, '%')
AND a1.agent_name like concat('%', #{agentName}, '%')
AND a1.is_real_name = #{isRealName}
AND a1.is_enabled = #{isEnabled}
AND a1.level = #{level}
ORDER BY a1.create_time desc limit #{offset},#{pageSize}

SELECT agentCode, agentName, totalOrders, activatedOrders, totalCommission, downstreamAgentCount, ROW_NUMBER() OVER (ORDER BY totalOrders DESC, createTime ASC) as ranking FROM ( SELECT a.agent_code as agentCode, a.agent_name as agentName, a.create_time as createTime, COALESCE(o.total_orders, 0) as totalOrders, COALESCE(o.activated_orders, 0) as activatedOrders, COALESCE(commission.total_commission, 0) as totalCommission, COALESCE(downstream.downstream_count, 0) as downstreamAgentCount FROM t_agent_account a LEFT JOIN ( SELECT downstream_code, COUNT(*) as total_orders, SUM(CASE WHEN order_status = 4 THEN 1 ELSE 0 END) as activated_orders FROM t_order WHERE 1=1
AND create_time >= #{startTime} AND create_time <= #{endTime}
GROUP BY downstream_code ) o ON a.agent_code = o.downstream_code LEFT JOIN ( SELECT downstream_agent_code, SUM(CASE WHEN order_status = 4 AND order_commission_status = 3 THEN product_commission ELSE 0 END) as total_commission FROM t_order_commission WHERE 1=1
AND order_create_time >= #{startTime} AND order_create_time <= #{endTime}
GROUP BY downstream_agent_code ) commission ON a.agent_code = commission.downstream_agent_code LEFT JOIN ( SELECT parent_agent_code, COUNT(*) as downstream_count FROM t_agent_account WHERE parent_agent_code IS NOT NULL AND parent_agent_code != '' GROUP BY parent_agent_code ) downstream ON a.agent_code = downstream.parent_agent_code WHERE a.sys_user_id != 1
AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')
) ranked_agents ORDER BY totalOrders DESC, createTime ASC LIMIT #{offset}, #{pageSize}
